import { resolveImagePath } from '../services/storage.service.js';
import { AppError } from '../utils/AppError.js';

// Streams an uploaded image. Only keys generated by the storage service are
// accepted, so "../" tricks cannot reach other files.
export async function getImage(req, res) {
  const resolved = resolveImagePath(req.params.key);
  if (!resolved) throw AppError.notFound('Image');

  res.set({
    'Content-Type': resolved.mimeType,
    'X-Content-Type-Options': 'nosniff',
    'Content-Security-Policy': "default-src 'none'",
    'Cache-Control': 'private, max-age=86400',
  });
  // The `root` option makes Express refuse any path that escapes the upload directory.
  res.sendFile(resolved.key, { root: resolved.root }, (err) => {
    if (err && !res.headersSent) {
      res.status(404).json({ success: false, error: { code: 'NOT_FOUND', message: 'Image not found' } });
    }
  });
}
